'use strict';
function sample(list){return list[Math.floor(Math.random()*list.length)]}
function openShop(){
 state='shop';shopTurn=0;
 const s=guns.map((g,i)=>g.rarity==='S'?i:-1).filter(i=>i>=0),r=sample(relics.map((_,i)=>i)),r2=sample(relics.map((_,i)=>i).filter(i=>i!==r));
 shopOffers=[{kind:'weapon',id:sample([16,18]),price:45},{kind:'weapon',id:sample([17,19]),price:60},{kind:'weapon',id:sample(s),price:90},{kind:'relic',id:r,price:40},{kind:'relic',id:r2,price:40},{kind:'pulse',id:0,price:25}];
 renderShop();
}
function shopBlockReason(player,index){const offer=shopOffers[index],p=players[player];if(!offer||!p)return '無効';if(shopReady[player])return '準備完了';if(shopBought[player].includes(index))return '購入済み';if(shopBought[player].length>=2)return '購入上限';if(credits[player]<offer.price)return '資金不足';if(offer.kind==='weapon'&&p.inventory.some(w=>w.id===offer.id))return '所持済み';if(offer.kind==='weapon'&&p.inventory.length>=4)return '武器が満杯';if(offer.kind==='relic'&&(p.relics.includes(offer.id)||p.relics.length>=3))return '装備不可';if(offer.kind==='pulse'&&p.blanks>=4)return 'パルス上限';return ''}
function buyShop(player,index){if(state!=='shop'||player!==shopTurn||shopBlockReason(player,index))return false;const o=shopOffers[index],p=players[player];let success=true;if(o.kind==='weapon')success=!!addGun(p,o.id);if(o.kind==='relic')success=addRelic(p,o.id);if(o.kind==='pulse')p.blanks++;if(!success)return false;credits[player]-=o.price;shopBought[player].push(index);updateHUD();if(!(mode==='cpu'&&player===1))renderShop();return true}
function readyShop(){if(state!=='shop'||shopReady[shopTurn])return;shopReady[shopTurn]=true;if(shopTurn===0){shopTurn=1;if(mode==='cpu'){const gunChoices=[0,1].filter(i=>!shopBlockReason(1,i));if(gunChoices.length)buyShop(1,sample(gunChoices));const relicChoices=[3,4].filter(i=>!shopBlockReason(1,i));if(relicChoices.length)buyShop(1,sample(relicChoices));shopReady[1]=true;launchRound();return}renderShop();return}if(shopReady.every(Boolean))launchRound()}
function renderShop(){const p=players[shopTurn],bonus=100+Math.min(30,Math.max(0,scores[1-shopTurn]-scores[shopTurn])*15)-100;
 overlay(`<div class="shop"><div class="eyebrow">ROUND ${roundNo} / SUPPLY SHOP</div><div class="shopheading"><h2>P${shopTurn+1}：ラウンド準備</h2><strong>${credits[shopTurn]} CR</strong></div><p>予算100${bonus?' ＋ 追い上げ支援'+bonus:''} CR ／ 購入 ${shopBought[shopTurn].length} / 2点</p><div class="shopgrid">${shopOffers.map((o,i)=>{const reason=shopBlockReason(shopTurn,i),g=o.kind==='weapon'?guns[o.id]:o.kind==='relic'?relics[o.id]:null;return `<button class="weaponcard shopcard" data-buy="${i}" ${reason?'disabled':''} style="--rarity:${o.kind==='weapon'?RARITIES[g.rarity].color:g?.color||'#9bcedd'}">${o.kind==='weapon'?weaponArt(o.id):`<div class="glyph">${g?.glyph||'⊕'}</div>`}<small>${o.kind==='weapon'?g.rarity+' / 武器':o.kind==='relic'?'レリック':'補助'}</small><h3>${g?.name||'予備パルス'}</h3><p>${g?.desc||'このラウンドだけパルス+1。最大4回まで。'}</p><b>${o.price} CR</b><span class="shopreason">${reason||'購入'}</span></button>`}).join('')}</div><div class="shopfooter"><p>同じ品揃え・各自の在庫。資金・購入品は次ラウンドに持ち越しません。<br>買わずに開始も可能。${mode==='local'?'P1 → P2 の順で購入します。':'CPUも同じ予算と購入上限です。'}</p><button class="primary" id="shopready">${shopTurn===0&&mode==='local'?'購入完了・P2へ':'準備完了・対戦開始'}</button></div></div>`);
 $('overlay').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>buyShop(shopTurn,+b.dataset.buy));$('shopready').onclick=readyShop;
}
